'use strict';
(() => {
const dialog=document.getElementById('scanner'),cam=document.getElementById('camera-video'),plane=document.getElementById('poster-plane'),status=document.getElementById('scan-status'),quality=document.getElementById('ar-quality'),enable=document.getElementById('enable-camera'),guide=document.getElementById('ar-guide'),demoVideo=document.getElementById('ar-demo-video'),sheet=document.getElementById('ar-sheet');
const switchCamera=document.getElementById('switch-camera');
let facing='environment';
const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});
let stream=null,worker=null,timer=null,session=0,focusReturn=null,busy=false,lastGood=0,pose=null,source=null,mode='off',pendingFrames=0;
function hideOverlay(){plane.hidden=true;pose=null;lastGood=0;demoVideo.pause();quality.classList.remove('locked');}
function stop(){session++;clearTimeout(timer);if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;cam.srcObject=null;if(worker)worker.terminate();worker=null;busy=false;source=null;mode='off';cam.hidden=false;pendingFrames=0;hideOverlay();enable.disabled=false;enable.hidden=false;switchCamera.hidden=true;guide.hidden=false;quality.textContent='Camera off';dialog.querySelector('.ar-stage').style.backgroundImage='none';}
function close(){stop();sheet.hidden=true;dialog.close();if(document.fullscreenElement===dialog)document.exitFullscreen?.().catch(()=>{});focusReturn?.focus();}
function open(button){focusReturn=button;sheet.hidden=true;status.textContent='Frame the entire poster, including the four corner markers.';dialog.showModal();}
document.querySelectorAll('[data-camera]').forEach(b=>b.addEventListener('click',()=>open(b)));
document.getElementById('close-camera').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
document.getElementById('camera-fallback').addEventListener('click',()=>{close();document.getElementById('explore').scrollIntoView();});
function resizePose(){if(!pose||!source)return;const sw=source.videoWidth||source.naturalWidth,sh=source.videoHeight||source.naturalHeight,box=dialog.querySelector('.ar-stage').getBoundingClientRect(),v=PosterTracking.viewport(sw,sh,box.width,box.height,mode==='camera');const m=PosterTracking.cssMatrix(pose,v.width,v.height,v.left,v.top);plane.style.transform='matrix3d('+m.join(',')+')';}
function startWorker(s){worker=new Worker('ar-worker.js');worker.onmessage=e=>{if(s!==session||e.data.session!==session)return;busy=false;const r=e.data;if(r.locked){pose=r.h;lastGood=performance.now();pendingFrames++;quality.textContent=(mode==='preview'?'PREVIEW · ':'LOCKED · ')+r.count+'/4 markers';quality.classList.add('locked');guide.hidden=true;status.textContent=mode==='preview'?'Preview only—this uses a poster image, not your camera.':'Tap a glowing hotspot. Keep the corners in view.';resizePose();plane.hidden=false;if(demoVideo.paused)demoVideo.play().catch(()=>{});}else{hideOverlay();pendingFrames=0;guide.hidden=false;quality.textContent=(mode==='preview'?'Preview · ':'Finding poster · ')+r.count+'/4 markers';status.textContent=r.reason==='error'?'Tracking could not start. Explore the poster without the camera.':'Show at least 3 corner markers. Hold steady and avoid glare.';}if(mode==='camera')timer=setTimeout(frame,80);};worker.onerror=()=>{busy=false;hideOverlay();status.textContent='Tracking is unavailable in this browser. Explore without the camera.';stop();};}
function frame(){if(!source||busy||!dialog.open)return;const sw=source.videoWidth||source.naturalWidth,sh=source.videoHeight||source.naturalHeight;if(!sw||!sh){timer=setTimeout(frame,150);return;}const scale=Math.min(1,1920/Math.max(sw,sh));canvas.width=Math.round(sw*scale);canvas.height=Math.round(sh*scale);ctx.drawImage(source,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);busy=true;worker.postMessage({buffer:pixels.data.buffer,width:canvas.width,height:canvas.height,session},[pixels.data.buffer]);}
async function startCamera(){stop();const s=++session;enable.disabled=true;status.textContent='Allow camera access in your browser. You can close this at any time.';quality.textContent='Waiting for permission';if(dialog.requestFullscreen)dialog.requestFullscreen().catch(()=>{});try{if(!navigator.mediaDevices?.getUserMedia)throw Object.assign(new Error('Camera API unavailable'),{name:'CameraUnavailable'});const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:1920},height:{ideal:2560},aspectRatio:{ideal:Math.min(1,window.innerWidth/window.innerHeight)}},audio:false});if(s!==session||!dialog.open){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;cam.srcObject=stream;await cam.play();if(s!==session)return;source=cam;mode='camera';enable.hidden=true;switchCamera.hidden=false;quality.textContent='Finding poster';status.textContent='Move back until the whole poster and its four markers are in view.';startWorker(s);frame();}catch(e){if(s!==session)return;stop();const messages={NotAllowedError:'Camera permission was denied. Allow camera access in your browser’s site settings, then try again.',NotFoundError:'No camera was found. Open this page in Safari or Chrome on your phone.',NotReadableError:'The camera is busy. Close other camera apps, then try again.',CameraUnavailable:'Camera access needs HTTPS or localhost. Open the secure website in Safari or Chrome.'};status.textContent=messages[e.name]||'The camera could not start. Try again or use Preview without camera.';}}
enable.addEventListener('click',startCamera);
switchCamera.addEventListener('click',()=>{facing=facing==='environment'?'user':'environment';startCamera();});
document.getElementById('preview-ar').addEventListener('click',async()=>{stop();const s=++session;mode='preview';cam.hidden=true;quality.textContent='Loading preview';status.textContent='Loading a poster image—no camera is used.';const image=new Image();image.src='assets/poster-tracking-preview.jpg';try{await image.decode();if(s!==session)return;source=image;dialog.querySelector('.ar-stage').style.backgroundImage='url("assets/poster-tracking-preview.jpg")';dialog.querySelector('.ar-stage').style.backgroundSize='contain';dialog.querySelector('.ar-stage').style.backgroundPosition='center';dialog.querySelector('.ar-stage').style.backgroundRepeat='no-repeat';startWorker(s);frame();}catch{stop();status.textContent='Preview could not load. The interactive sections still work without a camera.';}});
const detail={models:{title:'Four model paths. One film.',text:'Text predicts tokens, latent diffusion refines images, video models refine clips across space and time, and audio models decode sound. Tap through the model explanations to inspect each path.',href:'?s=models#explore',label:'Explore the models'},workflow:{title:'A real ComfyUI example',text:'This is the official Wan 2.2 example clip, rather than a film made by our group. The printed workflow shows separate published examples. Source [3] explains its nodes and settings.',href:'references.html#ref-3',label:'Open the original workflow source'},impact:{title:'Possibilities and responsibility',text:'Read our group’s pros and cons, then try the release decisions about consent, continuity and trust. The reference page provides the evidence and its limits.',href:'?s=impact#explore',label:'Explore our pros and cons'}};
document.querySelectorAll('[data-ar-section]').forEach(b=>b.addEventListener('click',()=>{const d=detail[b.dataset.arSection];document.getElementById('ar-sheet-content').innerHTML='<h2>'+d.title+'</h2><p>'+d.text+'</p><a href="'+d.href+'">'+d.label+' ↗</a>';document.querySelector('#ar-sheet-content a').addEventListener('click',stop);sheet.hidden=false;document.getElementById('close-ar-sheet').focus();}));document.getElementById('close-ar-sheet').addEventListener('click',()=>sheet.hidden=true);
window.addEventListener('resize',resizePose);cam.addEventListener('resize',()=>{hideOverlay();});window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden&&(mode!=='off'||enable.disabled)){stop();status.textContent='Camera paused. Enable it again when you return.';}});
// Never leave an old pose apparently locked if frame processing stalls.
setInterval(()=>{if(mode==='camera'&&lastGood&&performance.now()-lastGood>1200){hideOverlay();quality.textContent='Tracking paused';status.textContent='Tracking paused. Hold the full poster in view.';}},250);
})();
